#pragma once

#include "endweave/protocol/version.h"

#include <algorithm>
#include <bedrock/protocol/nbt.hpp>
#include <bedrock/protocol/stream.hpp>
#include <cstdint>
#include <string>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>

namespace bp = bedrock::protocol;

namespace endweave {

/** How one block type becomes the other version's across a hop. `states` lists every value of
 * each of its states, so every one of its blocks can be numbered. Generated by
 * tools/generate_block_states.py. */
struct BlockStateUpdate {
    std::string name;
    std::vector<std::pair<std::string, std::vector<bp::Tag>>> states = {};
    std::string rename = {};
    bp::CompoundTag add = {};
    std::vector<std::string> remove = {};
};

/** The block types whose states change across one hop. */
template <int From, int To>
std::vector<BlockStateUpdate> getBlockStateUpdates();

namespace detail {

inline void writeString(bp::BinaryWriter &dos, std::string_view value)
{
    dos.write<std::int16_t>(value.size());
    dos.writeRawBytes(value);
}

/** BDS NbtIo::write into a StringByteOutput: little-endian with fixed-width numbers and string
 * lengths, where bp::nbt writes the network form. Block states only hold these four types. */
inline void writeTag(bp::BinaryWriter &dos, const bp::Tag &tag)
{
    tag.visit([&](const auto &payload) {
        using T = std::decay_t<decltype(payload)>;
        if constexpr (std::is_same_v<T, bp::ByteTag>) {
            dos.write<std::int8_t>(payload.value());
        }
        else if constexpr (std::is_same_v<T, bp::IntTag>) {
            dos.write<std::int32_t>(payload.value());
        }
        else if constexpr (std::is_same_v<T, bp::StringTag>) {
            writeString(dos, payload.value());
        }
        else if constexpr (std::is_same_v<T, bp::CompoundTag>) {
            for (const auto &[name, child] : payload) {
                dos.write<std::uint8_t>(static_cast<std::uint8_t>(child.type()));
                writeString(dos, name);
                writeTag(dos, child);
            }
            dos.write<std::uint8_t>(static_cast<std::uint8_t>(bp::nbt::Type::End));
        }
    });
}

} // namespace detail

/** BDS Block::computeRawSerializationIdHashForNetwork: FNV-1a over the block's name and states as
 * NbtIo::write puts them into a StringByteOutput. */
inline std::uint32_t computeRawSerializationIdHashForNetwork(std::string_view name, const bp::CompoundTag &states)
{
    const bp::CompoundTag tag{{"name", bp::StringTag{std::string(name)}}, {"states", states}};
    std::string buffer;
    bp::BinaryWriter dos{buffer};
    dos.write<std::uint8_t>(static_cast<std::uint8_t>(bp::nbt::Type::Compound));
    detail::writeString(dos, "");
    detail::writeTag(dos, tag);
    std::uint32_t hash = 0x811C9DC5;
    for (const char byte : buffer) {
        hash = (hash ^ static_cast<std::uint8_t>(byte)) * 0x01000193;
    }
    return hash;
}

/** Calls `visit(states, updated)` for every block of `update`'s type, with its states before the hop
 * and after it. */
template <class Visit>
void forEachBlock(const BlockStateUpdate &update, Visit &&visit)
{
    std::vector<std::size_t> value(update.states.size());
    while (true) {
        bp::CompoundTag states;
        for (std::size_t i = 0; i < update.states.size(); ++i) {
            states.insert_or_assign(update.states[i].first, update.states[i].second[value[i]]);
        }
        bp::CompoundTag updated = states;
        for (const auto &[state, tag] : update.add) {
            updated.insert_or_assign(state, tag);
        }
        for (const auto &state : update.remove) {
            updated.erase(state);
        }
        visit(states, updated);

        std::size_t i = 0;
        while (i < value.size() && ++value[i] == update.states[i].second.size()) {
            value[i++] = 0;
        }
        if (i == value.size()) {
            return;
        }
    }
}

namespace detail {

using BlockMappings = std::vector<std::pair<std::uint32_t, std::uint32_t>>;

inline void addBlockMappings(const BlockStateUpdate &update, BlockMappings &mappings)
{
    forEachBlock(update, [&](const bp::CompoundTag &states, const bp::CompoundTag &updated) {
        const auto old_id = computeRawSerializationIdHashForNetwork(update.name, states);
        const auto new_id =
            computeRawSerializationIdHashForNetwork(update.rename.empty() ? update.name : update.rename, updated);
        if (old_id != new_id) {
            mappings.emplace_back(old_id, new_id);
        }
    });
}

/** Every block one hop renumbers, sorted by its id at `From`. */
template <int From, int To>
const BlockMappings &getBlockMappings()
{
    static const BlockMappings mappings = [] {
        BlockMappings result;
        for (const auto &update : getBlockStateUpdates<From, To>()) {
            addBlockMappings(update, result);
        }
        std::ranges::sort(result);
        return result;
    }();
    return mappings;
}

} // namespace detail

/** The id `To` gives the block `From` calls `id`, one hop at a time. A block no hop changes, such
 * as an add-on's, keeps its id.
 * @see ViaVersion MappingData#getNewBlockStateId. */
template <int From, int To>
std::uint32_t getNewBlockStateId(std::uint32_t id)
{
    if constexpr (From == To) {
        return id;
    }
    else {
        constexpr int next = step(From, To);
        const auto &mappings = detail::getBlockMappings<From, next>();
        const auto it = std::ranges::lower_bound(mappings, id, {}, &detail::BlockMappings::value_type::first);
        return getNewBlockStateId<next, To>(it != mappings.end() && it->first == id ? it->second : id);
    }
}

/** The states a hop adds that BDS works out from the blocks around them. A hop that adds any
 * specialises it with `connects(id)`, and `connect(pos, id, get)`, which gives the id the block at
 * `pos` takes from its neighbours, read through `get(pos)`.
 * @see ViaVersion ConnectionData. */
template <int From, int To>
struct ConnectionData {};

template <int From, int To>
concept HasConnections = requires(std::uint32_t id) { ConnectionData<From, To>::connects(id); };

} // namespace endweave
